using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher that flags <c>for</c>/<c>while</c> loops whose body contains BOTH
/// a real delay call (<c>Task.Delay</c>/<c>Thread.Sleep</c>) AND an invocation whose
/// receiver or arguments involve <c>IGitInvoker</c>, <c>RunAsync</c>, or process types
/// (<c>Process.Start</c>, <c>ProcessStartInfo</c>). This is the <c>RunGitAsync</c>
/// bug shape: retrying a deterministic failure (e.g. exit-128 <c>fatal: not a git
/// repository</c>) that can never succeed, burning wall-clock time with backoff sleeps.
///
/// <para>For each reported loop the matcher notes the attempt-count constant from the
/// loop bound, backoff-delay constants from delay expressions, and whether any
/// identifier in the loop body suggests failure classification (<c>isSuccess</c>,
/// <c>isSuccessExit</c>, <c>*Classifier*</c>, <c>shouldRetry</c>, or a
/// <c>Func&lt;int,bool&gt;</c>). A classifier does NOT exempt the loop — the finding
/// is still reported — but its presence is noted so a reviewer can decide whether the
/// retry is reasonable.</para>
///
/// <para>No I/O, no git — callers supply the (path, source) pairs. Self-exempts the
/// matcher's own fixture carriers.</para>
/// </summary>
public static class RetryDelayLoopsGuard
{
    /// <summary>Describes a retry-delay-loop violation (1-based <paramref name="Line"/>).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    private static readonly string[] SelfExemptFileNames =
        ["RetryDelayLoopsGuard.cs", "RetryDelayLoopsGuardTests.cs"];

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    /// <summary>
    /// Returns every retry-delay-loop violation across <paramref name="files"/>,
    /// ordered by path (ordinal) then line.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, string Source)> files)
    {
        var violations = new List<Violation>();

        foreach (var (path, source) in files)
        {
            if (SelfExemptFileNames.Contains(Path.GetFileName(path)))
                continue;

            var tree = CSharpSyntaxTree.ParseText(source, ParseOptions);
            ScanTree(path, tree, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    /// <summary>
    /// Returns every retry-delay-loop violation across <paramref name="trees"/>,
    /// ordered by path (ordinal) then line. Uses pre-parsed <see cref="SyntaxTree"/>
    /// objects.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var violations = new List<Violation>();

        foreach (var (path, tree) in trees)
        {
            if (SelfExemptFileNames.Contains(Path.GetFileName(path)))
                continue;

            ScanTree(path, tree, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    private static void ScanTree(string path, SyntaxTree tree, List<Violation> sink)
    {
        var text = tree.GetText();
        var root = tree.GetRoot();

        foreach (var loop in root.DescendantNodes().OfType<StatementSyntax>())
        {
            StatementSyntax? body;
            int loopKeywordPosition;

            switch (loop)
            {
                case ForStatementSyntax forStmt:
                    body = forStmt.Statement;
                    loopKeywordPosition = forStmt.ForKeyword.SpanStart;
                    break;
                case WhileStatementSyntax whileStmt:
                    body = whileStmt.Statement;
                    loopKeywordPosition = whileStmt.WhileKeyword.SpanStart;
                    break;
                default:
                    continue;
            }

            if (body is null)
                continue;

            var hasDelay = HasDelayCall(body);
            var hasGitOrProcessInvocation = HasGitOrProcessInvocation(body);

            if (!hasDelay || !hasGitOrProcessInvocation)
                continue;

            var line = LineOf(text, loopKeywordPosition);
            var reason = BuildReason(body);

            sink.Add(new Violation(path, line, SnippetOf(text, line), reason));
        }
    }

    private static bool HasDelayCall(SyntaxNode body)
    {
        foreach (var inv in body.DescendantNodes().OfType<InvocationExpressionSyntax>())
        {
            if (inv.Expression is not MemberAccessExpressionSyntax ma)
                continue;

            var method = ma.Name.Identifier.Text;
            var owner = RightmostIdentifier(ma.Expression);

            if (method == "Sleep" && owner == "Thread")
                return true;
            if (method == "Delay" && owner == "Task")
                return true;
        }

        return false;
    }

    private static bool HasGitOrProcessInvocation(SyntaxNode body)
    {
        foreach (var inv in body.DescendantNodes().OfType<InvocationExpressionSyntax>())
        {
            if (inv.Expression is MemberAccessExpressionSyntax ma)
            {
                var method = ma.Name.Identifier.Text;
                // Any invocation involving RunAsync, Process.Start, or git-like names.
                if (method == "RunAsync")
                    return true;

                var receiver = RightmostIdentifier(ma.Expression);
                if (receiver == "Process" && method == "Start")
                    return true;

                // Also catch anything with GitInvoker in the receiver chain.
                if (ma.Expression.ToString().Contains("GitInvoker", StringComparison.Ordinal))
                    return true;
            }
        }

        // Also check for object creations of process types.
        foreach (var creation in body.DescendantNodes().OfType<ObjectCreationExpressionSyntax>())
        {
            var typeName = creation.Type.ToString();
            if (typeName.Contains("ProcessStartInfo", StringComparison.Ordinal))
                return true;
        }

        return false;
    }

    private static string BuildReason(SyntaxNode body)
    {
        // Extract attempt-count constant from the loop.
        var attemptInfo = ExtractConstants(body);
        var classifierInfo = HasClassifier(body) ? " (classifier present)" : " (no classifier)";

        return $"retry-delay-loop: loop body contains both a delay and a git/process invocation — " +
               $"retrying a deterministic failure that may never succeed{attemptInfo}{classifierInfo}";
    }

    private static string ExtractConstants(SyntaxNode body)
    {
        // Walk up to the enclosing for/while and extract constants from the condition / initializer.
        var loop = body.Parent;
        var constants = new List<string>();

        if (loop is ForStatementSyntax forStmt)
        {
            // Look for `int attempt = 1; attempt <= 3; attempt++` — extract the bound.
            if (forStmt.Condition is BinaryExpressionSyntax cond
                && cond.Right is LiteralExpressionSyntax lit)
            {
                constants.Add($"maxAttempts={lit.Token.ValueText}");
            }
        }

        if (loop is WhileStatementSyntax whileStmt)
        {
            if (whileStmt.Condition is BinaryExpressionSyntax cond
                && cond.Right is LiteralExpressionSyntax lit)
            {
                constants.Add($"bound={lit.Token.ValueText}");
            }
        }

        // Find delay durations in the body.
        foreach (var inv in body.DescendantNodes().OfType<InvocationExpressionSyntax>())
        {
            if (inv.Expression is MemberAccessExpressionSyntax ma
                && ma.Name.Identifier.Text is "Delay" or "Sleep"
                && inv.ArgumentList.Arguments.Count > 0)
            {
                var firstArg = inv.ArgumentList.Arguments[0].Expression;
                if (firstArg is LiteralExpressionSyntax litArg)
                {
                    constants.Add($"delay={litArg.Token.ValueText}ms");
                }
                else
                {
                    var argText = firstArg.ToString();
                    if (argText.Length <= 60)
                        constants.Add($"delay={argText}");
                }
            }
        }

        return constants.Count > 0 ? $" [{string.Join(", ", constants)}]" : "";
    }

    private static bool HasClassifier(SyntaxNode body)
    {
        foreach (var ident in body.DescendantNodes().OfType<IdentifierNameSyntax>())
        {
            var name = ident.Identifier.Text;
            // Check for classifiers like isSuccess, isSuccessExit, *Classifier*, shouldRetry.
            if (name.Contains("isSuccess", StringComparison.OrdinalIgnoreCase)
                || name.Contains("Classifier", StringComparison.Ordinal)
                || name.Contains("shouldRetry", StringComparison.OrdinalIgnoreCase)
                || name.Contains("isTransient", StringComparison.OrdinalIgnoreCase))
                return true;
        }

        // Also check for Func<int, bool> style delegates.
        foreach (var gen in body.DescendantNodes().OfType<GenericNameSyntax>())
        {
            if (gen.Identifier.Text == "Func")
                return true;
        }

        return false;
    }

    private static string RightmostIdentifier(ExpressionSyntax expr) => expr switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        MemberAccessExpressionSyntax ma => ma.Name.Identifier.Text,
        _ => string.Empty,
    };

    private static int LineOf(SourceText text, int position) =>
        text.Lines.GetLinePosition(position).Line + 1;

    private static string SnippetOf(SourceText text, int line)
    {
        var s = text.Lines[line - 1].ToString().Trim();
        return s.Length <= 200 ? s : s[..200];
    }
}

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher that flags dependency-injection bypasses — method parameters that
/// default to a real collaborator (<c>?? new GitInvoker()</c>,
/// <c>?? TimeProvider.System</c>) on an optional parameter, PLUS every call site
/// of that method which omits the argument while the enclosing class holds a
/// <c>RelayDriverDependencies</c> field or property. This is the
/// <c>EarlyImplementationDetector</c> bug shape: an injection seam silently
/// bypassed because the caller forgets to pass the injected dependency.
///
/// <para>Two-pass syntax-tree analysis:
/// <b>Pass 1</b> — find methods with optional params (= null default) where the
/// method body does <c>param ?? new GitInvoker()</c> or
/// <c>param ?? TimeProvider.System</c>. Record (containing-type-name, method-name,
/// param-index, default-kind).
/// <b>Pass 2</b> — walk all invocations matching recorded method names; when the
/// bypassed param-index argument is omitted, check if the enclosing
/// <c>ClassDeclarationSyntax</c> contains a field/property typed
/// <c>RelayDriverDependencies</c> (by type-name identifier match). Report the call
/// site with method name, omitted param, and the bypass default.</para>
///
/// <para>Self-exempts the matcher's own fixture carriers. No I/O, no git.</para>
/// </summary>
public static class DiBypassGuard
{
    /// <summary>Describes a DI-bypass violation at a call site (1-based <paramref name="Line"/>).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    /// <summary>Records a bypassable method signature found in Pass 1.</summary>
    private sealed record BypassableMethod(
        string ContainingTypeName,
        string MethodName,
        int ParamIndex,
        string DefaultKind);

    private static readonly string[] SelfExemptFileNames =
        ["DiBypassGuard.cs", "DiBypassGuardTests.cs"];

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    /// <summary>
    /// Returns every DI-bypass violation across <paramref name="files"/>,
    /// ordered by path (ordinal) then line.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, string Source)> files)
    {
        var list = files as IReadOnlyCollection<(string Path, string Source)> ?? files.ToList();

        // Parse all files and extract info.
        var parsed = new List<(string Path, SyntaxNode Root, SourceText Text)>();
        foreach (var (path, source) in list)
        {
            if (SelfExemptFileNames.Contains(Path.GetFileName(path)))
                continue;

            var tree = CSharpSyntaxTree.ParseText(source, ParseOptions);
            parsed.Add((path, tree.GetRoot(), tree.GetText()));
        }

        return ComputeViolations(parsed);
    }

    /// <summary>
    /// Returns every DI-bypass violation across <paramref name="trees"/>,
    /// ordered by path (ordinal) then line. Uses pre-parsed <see cref="SyntaxTree"/>
    /// objects.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var parsed = new List<(string Path, SyntaxNode Root, SourceText Text)>();

        foreach (var (path, tree) in trees)
        {
            if (SelfExemptFileNames.Contains(Path.GetFileName(path)))
                continue;

            parsed.Add((path, tree.GetRoot(), tree.GetText()));
        }

        return ComputeViolations(parsed);
    }

    private static IReadOnlyList<Violation> ComputeViolations(
        List<(string Path, SyntaxNode Root, SourceText Text)> parsed)
    {
        // Pass 1 — find all bypassable methods.
        var bypassable = new List<(BypassableMethod Method, string Path)>();
        foreach (var (path, root, _) in parsed)
        {
            foreach (var method in root.DescendantNodes().OfType<MethodDeclarationSyntax>())
            {
                var typeName = GetEnclosingTypeName(method);
                if (typeName is null)
                    continue;

                var parameters = method.ParameterList.Parameters;
                for (int i = 0; i < parameters.Count; i++)
                {
                    var p = parameters[i];
                    // Must be an optional parameter with a null default.
                    if (p.Default is null || p.Default.Value is null)
                        continue;
                    if (p.Default.Value is not LiteralExpressionSyntax lit || lit.Kind() != SyntaxKind.NullLiteralExpression)
                        continue;

                    // Look in the method body for `param ?? new GitInvoker()` or `param ?? TimeProvider.System`.
                    var paramName = p.Identifier.Text;
                    var defaultKind = FindBypassDefault(method, paramName);
                    if (defaultKind is null)
                        continue;

                    bypassable.Add((new BypassableMethod(typeName, method.Identifier.Text, i, defaultKind), path));
                }
            }
        }

        if (bypassable.Count == 0)
            return [];

        // Build a lookup: methodName → list of (bypassable, defining-path).
        var byName = new Dictionary<string, List<(BypassableMethod Method, string DefiningPath)>>(StringComparer.Ordinal);
        foreach (var (method, defPath) in bypassable)
        {
            if (!byName.ContainsKey(method.MethodName))
                byName[method.MethodName] = [];
            byName[method.MethodName].Add((method, defPath));
        }

        // Pass 2 — find call sites that omit the bypassed argument.
        var violations = new List<Violation>();
        foreach (var (path, root, text) in parsed)
        {
            foreach (var inv in root.DescendantNodes().OfType<InvocationExpressionSyntax>())
            {
                string? methodName;
                if (inv.Expression is MemberAccessExpressionSyntax ma)
                    methodName = ma.Name.Identifier.Text;
                else if (inv.Expression is IdentifierNameSyntax id)
                    methodName = id.Identifier.Text;
                else
                    continue;

                if (!byName.TryGetValue(methodName, out var candidates))
                    continue;

                var argCount = inv.ArgumentList.Arguments.Count;

                foreach (var (candidate, defPath) in candidates)
                {
                    // If the invocation has enough arguments to cover the bypassed param, skip.
                    if (argCount > candidate.ParamIndex)
                        continue;

                    // If this is the defining file, and the invocation is inside the defining method itself, skip.
                    if (path == defPath)
                    {
                        var enclosingMethod = inv.FirstAncestorOrSelf<MethodDeclarationSyntax>();
                        if (enclosingMethod is not null && enclosingMethod.Identifier.Text == methodName)
                            continue;
                    }

                    // Check if enclosing class holds RelayDriverDependencies.
                    var enclosingClass = inv.FirstAncestorOrSelf<ClassDeclarationSyntax>();
                    if (enclosingClass is null || !HasRelayDriverDependencies(enclosingClass))
                        continue;

                    var line = LineOf(text, inv.SpanStart);
                    violations.Add(new Violation(path, line, SnippetOf(text, line),
                        $"di-bypass: call to `{candidate.ContainingTypeName}.{methodName}` omits parameter " +
                        $"#{candidate.ParamIndex + 1} (`{BypassedParamName(candidate)}`), which defaults to " +
                        $"{candidate.DefaultKind} — the enclosing class holds `RelayDriverDependencies`, " +
                        $"so an injected seam is silently bypassed"));
                }
            }
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    /// <summary>
    /// Looks inside <paramref name="method"/>'s body for a
    /// <c>paramName ?? new GitInvoker()</c> or <c>paramName ?? TimeProvider.System</c>
    /// expression. Returns the default kind string (e.g. "new GitInvoker()") or null.
    /// </summary>
    private static string? FindBypassDefault(MethodDeclarationSyntax method, string paramName)
    {
        if (method.Body is null && method.ExpressionBody is null)
            return null;

        var body = (SyntaxNode?)method.Body ?? method.ExpressionBody;
        if (body is null)
            return null;

        foreach (var coalesce in body.DescendantNodes().OfType<BinaryExpressionSyntax>())
        {
            if (!coalesce.IsKind(SyntaxKind.CoalesceExpression))
                continue;

            // Left side must be the parameter name.
            if (coalesce.Left is IdentifierNameSyntax ident && ident.Identifier.Text == paramName)
            {
                var right = coalesce.Right;
                var rightText = right.ToString();
                if (rightText.Contains("new GitInvoker()", StringComparison.Ordinal))
                    return "new GitInvoker()";
                if (rightText.Contains("TimeProvider.System", StringComparison.Ordinal))
                    return "TimeProvider.System";
            }
        }

        return null;
    }

    private static string? GetEnclosingTypeName(MethodDeclarationSyntax method)
    {
        var type = method.FirstAncestorOrSelf<TypeDeclarationSyntax>();
        return type?.Identifier.Text;
    }

    private static bool HasRelayDriverDependencies(ClassDeclarationSyntax cls)
    {
        foreach (var member in cls.Members)
        {
            if (member is FieldDeclarationSyntax field)
            {
                if (field.Declaration.Type.ToString().Contains("RelayDriverDependencies", StringComparison.Ordinal))
                    return true;
            }
            else if (member is PropertyDeclarationSyntax prop)
            {
                if (prop.Type.ToString().Contains("RelayDriverDependencies", StringComparison.Ordinal))
                    return true;
            }
        }

        return false;
    }

    private static string BypassedParamName(BypassableMethod m)
    {
        return m.DefaultKind switch
        {
            "new GitInvoker()" => "gitInvoker/gi",
            "TimeProvider.System" => "timeProvider/tp",
            _ => "?",
        };
    }

    private static int LineOf(SourceText text, int position) =>
        text.Lines.GetLinePosition(position).Line + 1;

    private static string SnippetOf(SourceText text, int line)
    {
        var s = text.Lines[line - 1].ToString().Trim();
        return s.Length <= 200 ? s : s[..200];
    }
}

using System.Text.RegularExpressions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher that combines two complementary diagnostics for the
/// <c>./visual-relay audit real-waits</c> rule:
///
/// <list type="number">
///   <item><b>Active violations:</b> delegates to
///         <see cref="RealSleepGuard.FindViolations(IEnumerable{ValueTuple{string, string}})"/>
///         across all non-self-exempt files, tagging findings with a
///         <c>"real-waits: "</c> prefix so the audit renderer can distinguish them.
///         Self-exempts its own fixture carriers AND
///         <see cref="RealSleepGuard"/>'s self-exempt/re-integration-exempt files.</item>
///   <item><b>Suppression inventory:</b> scans every source's text lines for
///         <c>// vr-allow-sleep:</c> markers (with or without a reason) and reports
///         them via <see cref="FindSuppressions"/> so stale exemptions get
///         re-reviewed instead of living forever. Each entry includes the file,
///         line, and the reason text after the colon.</item>
/// </list>
///
/// <para>Self-exempts the matcher's own fixture carriers AND everything
/// <see cref="RealSleepGuard"/> exempts. No I/O, no git — callers supply the
/// (path, source) pairs.</para>
/// </summary>
public static class RealWaitsGuard
{
    /// <summary>Describes a real-wait finding (1-based <paramref name="Line"/>).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    /// <summary>Describes a <c>// vr-allow-sleep:</c> suppression marker.</summary>
    public sealed record Suppression(string Path, int Line, string Reason);

    /// <summary>Matches a <c>// vr-allow-sleep:</c> line capturing the optional reason after the colon.</summary>
    private static readonly Regex AllowSleepMarker =
        new(@"//\s*vr-allow-sleep:\s*(.*)", RegexOptions.Compiled);

    private static readonly string[] SelfExemptFileNames =
        ["RealWaitsGuard.cs", "RealWaitsGuardTests.cs"];

    /// <summary>Plus all of RealSleepGuard's self-exempt and real-integration-exempt files.</summary>
    private static readonly string[] RealSleepExemptFileNames =
        ["RealSleepGuard.cs", "RealSleepGuardTests.cs"];

    private static readonly string[] RealIntegrationExemptFileNames =
    [
        "ProcessCaptureGracefulStopTests.cs",
        "SandboxedTestRunnerReapTests.cs",
        "ActivityWatchdogSocketWedgeTests.cs",
        "FdLeakTests.cs",
        "WindowsExecutionTests.cs",
    ];

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    private static bool IsExempt(string fileName) =>
        SelfExemptFileNames.Contains(fileName)
        || RealSleepExemptFileNames.Contains(fileName)
        || RealIntegrationExemptFileNames.Contains(fileName);

    /// <summary>
    /// Returns every real-wait violation across <paramref name="files"/>,
    /// ordered by path (ordinal) then line. Delegates to
    /// <see cref="RealSleepGuard.FindViolations(IEnumerable{ValueTuple{string, string}})"/>
    /// and re-tags findings with a <c>"real-waits: "</c> prefix.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, string Source)> files)
    {
        var list = files as IReadOnlyCollection<(string Path, string Source)> ?? files.ToList();

        // Filter out exempt files.
        var filtered = list
            .Where(f => !IsExempt(Path.GetFileName(f.Path)))
            .ToList();

        if (filtered.Count == 0)
            return [];

        var sleepViolations = RealSleepGuard.FindViolations(filtered);

        var violations = new List<Violation>(sleepViolations.Count);
        foreach (var sv in sleepViolations)
        {
            violations.Add(new Violation(sv.Path, sv.Line, sv.Snippet,
                $"real-waits: {sv.Reason}"));
        }

        return violations;
    }

    /// <summary>
    /// Returns every real-wait violation across <paramref name="trees"/>,
    /// ordered by path (ordinal) then line. Uses pre-parsed <see cref="SyntaxTree"/>
    /// objects.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var list = trees as IReadOnlyCollection<(string Path, SyntaxTree Tree)> ?? trees.ToList();

        var filtered = list
            .Where(f => !IsExempt(Path.GetFileName(f.Path)))
            .ToList();

        if (filtered.Count == 0)
            return [];

        var sleepViolations = RealSleepGuard.FindViolations(filtered);

        var violations = new List<Violation>(sleepViolations.Count);
        foreach (var sv in sleepViolations)
        {
            violations.Add(new Violation(sv.Path, sv.Line, sv.Snippet,
                $"real-waits: {sv.Reason}"));
        }

        return violations;
    }

    /// <summary>
    /// Returns every <c>// vr-allow-sleep:</c> suppression marker across
    /// <paramref name="files"/>, ordered by path (ordinal) then line.
    /// Non-exempt files only.
    /// </summary>
    public static IReadOnlyList<Suppression> FindSuppressions(IEnumerable<(string Path, string Source)> files)
    {
        var suppressions = new List<Suppression>();

        foreach (var (path, source) in files)
        {
            if (IsExempt(Path.GetFileName(path)))
                continue;

            var lines = source.Split('\n');
            for (int i = 0; i < lines.Length; i++)
            {
                var match = AllowSleepMarker.Match(lines[i]);
                if (!match.Success)
                    continue;

                var reason = match.Groups[1].Value.Trim();
                if (reason.Length == 0)
                    reason = "(no reason given)";

                suppressions.Add(new Suppression(path, i + 1, reason));
            }
        }

        suppressions.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return suppressions;
    }

    /// <summary>
    /// Returns every <c>// vr-allow-sleep:</c> suppression marker across
    /// <paramref name="trees"/>, ordered by path (ordinal) then line.
    /// Uses pre-parsed <see cref="SyntaxTree"/> objects. Non-exempt files only.
    /// </summary>
    public static IReadOnlyList<Suppression> FindSuppressions(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var suppressions = new List<Suppression>();

        foreach (var (path, tree) in trees)
        {
            if (IsExempt(Path.GetFileName(path)))
                continue;

            var text = tree.GetText();
            foreach (var textLine in text.Lines)
            {
                var lineText = textLine.ToString();
                var match = AllowSleepMarker.Match(lineText);
                if (!match.Success)
                    continue;

                var reason = match.Groups[1].Value.Trim();
                if (reason.Length == 0)
                    reason = "(no reason given)";

                suppressions.Add(new Suppression(path, textLine.LineNumber + 1, reason));
            }
        }

        suppressions.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return suppressions;
    }
}

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher that flags test sources referencing real-side-effect constructs.
/// Four patterns are detected:
///
/// <list type="number">
///   <item><c>new GitInvoker(</c> — a real <c>GitInvoker</c> allocation in test
///         code; suggest <c>NullGitInvoker</c> (returns exit-128) or
///         <c>GitSim</c> (in-memory <c>IGitInvoker</c>).</item>
///   <item><c>Process.Start</c> — a real process launch in a test; suggest
///         <c>ScriptedTestRunner</c> or an in-process equivalent.</item>
///   <item><c>new ProcessStartInfo(</c> — configuring a real process; suggest
///         <c>ScriptedTestRunner</c>.</item>
///   <item><c>Environment.SetEnvironmentVariable</c> — mutating the OS environment
///         from a test; suggest <c>DictionaryEnvironmentAccessor</c>.</item>
/// </list>
///
/// <para>Only flags files whose path contains <c>/tests/</c> (non-test sources are
/// not reported). Honors <see cref="RealSleepGuard"/>'s slow-integration exemption
/// list (<see cref="RealIntegrationExemptFileNames"/>). Self-exempts the matcher's
/// own fixture carriers. No I/O, no git — callers supply the (path, source) pairs.</para>
/// </summary>
public static class TestSideEffectsGuard
{
    /// <summary>Describes a test-side-effect violation (1-based <paramref name="Line"/>).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    private static readonly string[] SelfExemptFileNames =
        ["TestSideEffectsGuard.cs", "TestSideEffectsGuardTests.cs"];

    /// <summary>Slow-integration files whose real side-effects are legitimate
    /// (only run behind <c>SlowIntegration.SkipIfNotOptedIn()</c>).</summary>
    private static readonly string[] RealIntegrationExemptFileNames =
    [
        "ProcessCaptureGracefulStopTests.cs",
        "SandboxedTestRunnerReapTests.cs",
        "ActivityWatchdogSocketWedgeTests.cs",
        "FdLeakTests.cs",
        "WindowsExecutionTests.cs",
    ];

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    /// <summary>
    /// Returns every test-side-effect violation across <paramref name="files"/>,
    /// ordered by path (ordinal) then line. Only flags files whose path contains
    /// <c>/tests/</c>.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, string Source)> files)
    {
        var violations = new List<Violation>();

        foreach (var (path, source) in files)
        {
            var fileName = Path.GetFileName(path);
            if (SelfExemptFileNames.Contains(fileName) || RealIntegrationExemptFileNames.Contains(fileName))
                continue;

            if (!path.Contains("/tests/", StringComparison.Ordinal))
                continue;

            var tree = CSharpSyntaxTree.ParseText(source, ParseOptions);
            ScanTree(path, tree, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    /// <summary>
    /// Returns every test-side-effect violation across <paramref name="trees"/>,
    /// ordered by path (ordinal) then line. Uses pre-parsed <see cref="SyntaxTree"/>
    /// objects.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var violations = new List<Violation>();

        foreach (var (path, tree) in trees)
        {
            var fileName = Path.GetFileName(path);
            if (SelfExemptFileNames.Contains(fileName) || RealIntegrationExemptFileNames.Contains(fileName))
                continue;

            if (!path.Contains("/tests/", StringComparison.Ordinal))
                continue;

            ScanTree(path, tree, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    private static void ScanTree(string path, SyntaxTree tree, List<Violation> sink)
    {
        var text = tree.GetText();
        var root = tree.GetRoot();

        foreach (var node in root.DescendantNodes())
        {
            switch (node)
            {
                // new GitInvoker()
                case ObjectCreationExpressionSyntax creation
                    when creation.Type is IdentifierNameSyntax id
                         && id.Identifier.Text == "GitInvoker":
                    Report(creation.SpanStart, "new GitInvoker()",
                        "prefer NullGitInvoker (returns exit-128) or GitSim (in-memory IGitInvoker)");
                    break;

                // Process.Start(...)
                case InvocationExpressionSyntax inv
                    when inv.Expression is MemberAccessExpressionSyntax ma
                         && RightmostIdentifier(ma.Expression) == "Process"
                         && ma.Name.Identifier.Text == "Start":
                    Report(inv.SpanStart, "Process.Start(...)",
                        "prefer ScriptedTestRunner or an in-process equivalent");
                    break;

                // new ProcessStartInfo(...)
                case ObjectCreationExpressionSyntax creation
                    when creation.Type is IdentifierNameSyntax psiId
                         && psiId.Identifier.Text == "ProcessStartInfo":
                    Report(creation.SpanStart, "new ProcessStartInfo(...)",
                        "prefer ScriptedTestRunner or an in-process equivalent");
                    break;

                // Environment.SetEnvironmentVariable
                case InvocationExpressionSyntax inv
                    when inv.Expression is MemberAccessExpressionSyntax envMa
                         && RightmostIdentifier(envMa.Expression) == "Environment"
                         && envMa.Name.Identifier.Text == "SetEnvironmentVariable":
                    Report(inv.SpanStart, "Environment.SetEnvironmentVariable(...)",
                        "prefer DictionaryEnvironmentAccessor (in-memory IEnvironmentAccessor)");
                    break;
            }

            continue;

            void Report(int position, string pattern, string direction)
            {
                var line = LineOf(text, position);
                sink.Add(new Violation(path, line, SnippetOf(text, line),
                    $"test-side-effects: {pattern} in test source — {direction}"));
            }
        }

        // De-duplicate per (line, reason).
        var seen = new HashSet<(int Line, string Reason)>();
        var deduped = new List<Violation>();
        foreach (var v in sink.OrderBy(v => v.Line))
        {
            if (seen.Add((v.Line, v.Reason)))
                deduped.Add(v);
        }

        sink.Clear();
        sink.AddRange(deduped);
    }

    private static string RightmostIdentifier(ExpressionSyntax expr) => expr switch
    {
        IdentifierNameSyntax id => id.Identifier.Text,
        MemberAccessExpressionSyntax ma => ma.Name.Identifier.Text,
        _ => string.Empty,
    };

    private static int LineOf(SourceText text, int position) =>
        text.Lines.GetLinePosition(position).Line + 1;

    private static string SnippetOf(SourceText text, int line)
    {
        var s = text.Lines[line - 1].ToString().Trim();
        return s.Length <= 200 ? s : s[..200];
    }
}

using System.Diagnostics;
using VisualRelay.Guards;

// VisualRelay.Audit — the diagnostic CLI for hermeticity findings.
// ./visual-relay audit [rule-id ...]
// No args = all four rules. Exit 0 when audit ran; exit 2 on unknown rule-id.
// Informational only — never a gate; see tasks 02-04 for the enforcing guard-as-tests.

var root = GuardRepoRoot.Resolve();
if (root is null)
{
    Console.Error.WriteLine("audit: could not find repo root.");
    return 1;
}

// Parse rule-id filter.
var allRuleIds = new[] { "retry-delay-loops", "di-bypass", "real-waits", "test-side-effects" };
var requestedRules = args.Length > 0
    ? args.Select(a => a.Trim().ToLowerInvariant()).ToArray()
    : allRuleIds;

foreach (var rule in requestedRules)
{
    if (!allRuleIds.Contains(rule))
    {
        Console.Error.WriteLine($"audit: unknown rule-id '{rule}' (expected: {string.Join("|", allRuleIds)}).");
        return 2;
    }
}

// Scan src/, tests/, tools/ for *.cs files.
var files = ScanSources(root);

var stopwatch = Stopwatch.StartNew();

var findings = new List<AuditRenderer.Finding>();

// Map rule-ids to matcher calls.
var registry = new Dictionary<string, Action>(StringComparer.OrdinalIgnoreCase)
{
    ["retry-delay-loops"] = () =>
    {
        var violations = RetryDelayLoopsGuard.FindViolations(files);
        foreach (var v in violations)
            findings.Add(new AuditRenderer.Finding("retry-delay-loops", v.Path, v.Line, v.Snippet, v.Reason,
                "This loop contains both a delay call (Task.Delay/Thread.Sleep) AND a git/process invocation.",
                "Consider: extract the delay from the retry loop, or make the operation idempotent so retry is unnecessary. Check if the failure being retried can ever succeed (e.g. exit-128 is deterministic)."));
    },
    ["di-bypass"] = () =>
    {
        var violations = DiBypassGuard.FindViolations(files);
        foreach (var v in violations)
            findings.Add(new AuditRenderer.Finding("di-bypass", v.Path, v.Line, v.Snippet, v.Reason,
                "A call site omits an optional parameter that defaults to a real collaborator, while the enclosing class holds RelayDriverDependencies with the injected seam.",
                "Pass the injected dependency explicitly, e.g. `_dependencies.GitInvoker` or `_dependencies.TimeProvider`."));
    },
    ["real-waits"] = () =>
    {
        var violations = RealWaitsGuard.FindViolations(files);
        foreach (var v in violations)
            findings.Add(new AuditRenderer.Finding("real-waits", v.Path, v.Line, v.Snippet, v.Reason,
                "A real wall-clock wait (Thread.Sleep, Task.Delay without TimeProvider, or shell sleep) was found.",
                "Drive the delay with a TimeProvider (virtual-clock seam) or use Task.Yield() for advance-yield loops. For shell sleeps, prefer an in-process equivalent or a virtual-clock-driven timer."));

        var suppressions = RealWaitsGuard.FindSuppressions(files);
        foreach (var s in suppressions)
            findings.Add(new AuditRenderer.Finding("real-waits:suppression", s.Path, s.Line, s.Reason,
                "A // vr-allow-sleep: suppression marker — the reason should be re-reviewed.",
                "Confirm the suppression reason is still valid. If the underlying need is gone, remove the suppression."));
    },
    ["test-side-effects"] = () =>
    {
        var violations = TestSideEffectsGuard.FindViolations(files);
        foreach (var v in violations)
            findings.Add(new AuditRenderer.Finding("test-side-effects", v.Path, v.Line, v.Snippet, v.Reason,
                "A test source references a real-side-effect construct.",
                "Replace with a hermetic double: NullGitInvoker/GitSim for GitInvoker, ScriptedTestRunner for Process.Start, DictionaryEnvironmentAccessor for Environment.SetEnvironmentVariable."));
    },
};

foreach (var rule in requestedRules)
{
    registry[rule]();
}

stopwatch.Stop();

AuditRenderer.Render(findings, stopwatch.Elapsed);

return 0;

// ── Helpers ──

static List<(string Path, string Source)> ScanSources(string root)
{
    var results = new List<(string Path, string Source)>();

    foreach (var dir in new[] { "src", "tests", "tools" })
    {
        var fullDir = Path.Combine(root, dir);
        if (!Directory.Exists(fullDir))
            continue;

        foreach (var file in Directory.EnumerateFiles(fullDir, "*.cs", SearchOption.AllDirectories))
        {
            if (IsBuildArtifact(file))
                continue;

            var relativePath = Path.GetRelativePath(root, file);
            var source = File.ReadAllText(file);
            results.Add((relativePath, source));
        }
    }

    return results;
}

static bool IsBuildArtifact(string path)
{
    var segments = path.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
    return segments.Any(s => s is "bin" or "obj");
}

namespace VisualRelay.Audit;

/// <summary>
/// Renders audit findings to STDOUT in a human-readable format:
/// <c>path:line: &lt;rule-id&gt;: &lt;message&gt;</c>, then indented explanation +
/// suggested-direction lines, then a per-rule summary table with total runtime.
/// </summary>
public static class AuditRenderer
{
    /// <summary>A single finding from one of the audit matchers.</summary>
    public sealed record Finding(
        string RuleId,
        string Path,
        int Line,
        string Snippet,
        string Message,
        string Explanation,
        string Direction);

    /// <summary>
    /// Renders <paramref name="findings"/> to <see cref="Console.Out"/> in the audit
    /// report format, followed by a summary table.
    /// </summary>
    public static void Render(IReadOnlyList<Finding> findings, TimeSpan elapsed)
    {
        if (findings.Count == 0)
        {
            Console.WriteLine("Audit complete: no findings.");
            Console.WriteLine();
            Console.WriteLine($"  rules: 4");
            Console.WriteLine($"  runtime: {elapsed.TotalSeconds:F1}s");
            return;
        }

        // Group findings by rule-id for ordered output.
        var ruleOrder = new[] { "retry-delay-loops", "di-bypass", "real-waits", "real-waits:suppression", "test-side-effects" };
        var grouped = findings
            .GroupBy(f => f.RuleId)
            .OrderBy(g => Array.IndexOf(ruleOrder, g.Key));

        foreach (var group in grouped)
        {
            Console.WriteLine($"── {group.Key} ({group.Count()} finding(s)) ──");
            Console.WriteLine();

            foreach (var f in group)
            {
                Console.WriteLine($"{f.Path}:{f.Line}: {f.RuleId}: {f.Message}");
                Console.WriteLine($"  explanation: {f.Explanation}");
                Console.WriteLine($"  direction: {f.Direction}");
                Console.WriteLine();
            }
        }

        // Summary table.
        Console.WriteLine("── Summary ──");
        Console.WriteLine();

        var counts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var f in findings)
        {
            var key = f.RuleId;
            counts.TryGetValue(key, out var c);
            counts[key] = c + 1;
        }

        Console.WriteLine($"  {'rule',-26} {'findings',>8}");
        Console.WriteLine($"  {new string('-', 26)} {new string('-', 8)}");
        foreach (var ruleId in ruleOrder)
        {
            if (counts.TryGetValue(ruleId, out var count))
                Console.WriteLine($"  {ruleId,-26} {count,>8}");
        }
        Console.WriteLine($"  {new string('-', 26)} {new string('-', 8)}");
        Console.WriteLine($"  {'total',-26} {findings.Count,>8}");
        Console.WriteLine();
        Console.WriteLine($"  runtime: {elapsed.TotalSeconds:F1}s");
    }
}

